<?php

declare(strict_types=1);

/**
 * F13 CI-only transport signer of the event generated by Portal F11.
 * Outputs test HMAC headers to a local runner file, no HTTP/real secrets.
 */
require_once __DIR__.'/SyntheticWireEnvelope.php';

use Imagine\Protocol\Lab\SyntheticWireEnvelope as Wire;

if (PHP_SAPI !== 'cli'
    || getenv('APP_ENV') !== 'testing'
    || getenv('PORTAL_CLIENT_LAB_ENABLED') !== '1'
    || getenv('PORTAL_PERF_F11_LAB_ENABLED') !== '1'
    || getenv('DB_HOST') !== '127.0.0.1'
    || getenv('DB_DATABASE') !== 'portal_lab') {
    throw new RuntimeException('F13 transport signing requires disposable CLI test.');
}
$tmp = realpath((string) getenv('RUNNER_TEMP'));
$source = getenv('PORTAL_F13_EVENT_EXPORT');
$target = getenv('PORTAL_F13_HEADERS_EXPORT');
if (!is_string($tmp) || !is_string($source) || !is_string($target)
    || realpath(dirname($source)) !== $tmp
    || realpath(dirname($target)) !== $tmp
    || basename($source) !== 'portal-perf-f13-event.json'
    || basename($target) !== 'portal-perf-f13-wire-headers.json'
    || !is_file($source) || is_link($source) || file_exists($target)) {
    throw new RuntimeException('Refusing non-temp F13 test transport files.');
}
$hex = getenv('PERF_WIRE_LAB_TEST_KEY_HEX');
if (!is_string($hex) || !preg_match('/^[a-f0-9]{64}$/D', $hex)) {
    throw new RuntimeException('Refusing non-ephemeral wire test key.');
}
$key = hex2bin($hex);
if (!is_string($key)) {
    throw new RuntimeException('Invalid ephemeral wire key.');
}
$body = file_get_contents($source);
if (!is_string($body) || strlen($body) < 80 || strlen($body) > Wire::MAX_BYTES) {
    throw new RuntimeException('F13 Portal test event is missing or too large.');
}
$event = json_decode($body, true, 512, JSON_THROW_ON_ERROR);
$fields = [
    'event_id','service_ref','organization_ref','tenant_ref',
    'source_revision','event_type','status','attempts'
];
if (!is_array($event) || array_keys($event) !== $fields
    || !is_string($event['event_id'])
    || !preg_match('/^evt-demo-[a-f0-9]{24}$/D', $event['event_id'])
    || $event['service_ref'] !== 'svc-demo-b'
    || $event['organization_ref'] !== 'org-demo-b'
    || $event['tenant_ref'] !== 'perf-demo-b'
    || $event['source_revision'] !== 2
    || $event['status'] !== 'pending'
    || $event['attempts'] !== 0) {
    throw new RuntimeException('Refusing non-canonical Portal F13 event.');
}

$headers = Wire::signForLab(
    $body, $key, 1800000000, 'nonce-demo-http-accepted001'
);
if (Wire::verifyForLab(Wire::METHOD, Wire::PATH, $body, $headers, $key, 1800000000)
    !== 'wire_valid_demo') {
    throw new RuntimeException('F13 signer failed local roundtrip verification.');
}
$output = json_encode($headers, JSON_THROW_ON_ERROR | JSON_PRETTY_PRINT);
if (file_put_contents($target, $output."\n", LOCK_EX) === false) {
    throw new RuntimeException('F13 header fixture write failed.');
}
chmod($target, 0600);
echo "PASS Portal F13 dynamically created and signed a synthetic revocation event\n";
